svg.script:
function initPong(evt) {
  const svgDoc = evt.target;
  const ballEl = svgDoc.getElementById('ball');
  const padLEl = svgDoc.getElementById('padL');
  const padREl = svgDoc.getElementById('padR');
  const ballTrailEl = svgDoc.getElementById('ballTrail');
  const gameContentEl = svgDoc.getElementById('gameContent');
  const textGroupEl = svgDoc.getElementById('textGroup');
  const wavesContainer = svgDoc.getElementById('wavesContainer');

  let ball = { x: 442, y: 152, vx: -8, vy: 4 };
  let padL = { y: 120, h: 80, target: 120, vy: 0 };
  let padR = { y: 120, h: 80, target: 120, vy: 0 };

  let sequence = [20, -20, 30, -30, 10, -10, 25, -25, 15, -15, 5, -5];
  let hitCount = 0;
  let frame = 0;
  let shakeFrames = 0;
  let speedMult = 1.0;
  const MAX_SPEED_MULT = 1.36;
  const bounds = 320 - 16;
  let ballHistory = []; 

  const waves = [];
  const nodes = [
    { x: 140, y: 156 },
    { x: 490, y: 156 }
  ];

  function createWave(x, y, isSecondary) {
    const wave = {
        x: x,
        y: y,
        r: 2,
        opacity: isSecondary ? 0.38 : 0.64,
        speed: isSecondary ? 1.5 : 3.5,
        fade: isSecondary ? 0.006 : 0.004,
        isSecondary: isSecondary,
        hitNodes: new Set()
    };
    waves.push(wave);
    const el = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
    el.setAttribute('cx', wave.x);
    el.setAttribute('cy', wave.y);
    el.setAttribute('class', 'wave');
    el.setAttribute('stroke-width', isSecondary ? 0.5 : 1.5);
    wave.element = el;
    wavesContainer.appendChild(el);
  }

  function predictY(startX, startY, vx, vy, targetX) {
    let dx = Math.abs(targetX - startX);
    let time = dx / Math.abs(vx);
    let yPos = startY + vy * time;
    while (yPos < 0 || yPos > bounds) {
        if (yPos < 0) yPos = -yPos;
        if (yPos > bounds) yPos = bounds - (yPos - bounds);
    }
    return yPos;
  }

  function updateActiveTarget(side) {
    let activeOffset = sequence[hitCount % 12];
    if (side === 'left') {
      let impactY = predictY(ball.x, ball.y, ball.vx, ball.vy, 30);
      padL.target = impactY - (padL.h / 2) + activeOffset;
      padL.target = Math.max(0, Math.min(320 - padL.h, padL.target));
    } else {
      let impactY = predictY(ball.x, ball.y, ball.vx, ball.vy, 870);
      padR.target = impactY - (padR.h / 2) + activeOffset;
      padR.target = Math.max(0, Math.min(320 - padR.h, padR.target));
    }
  }

  function loop() {
    frame++;
    ball.x += ball.vx;
    ball.y += ball.vy;

    if (ball.y <= 0 || ball.y >= bounds) {
      ball.vy *= -1;
      ball.y = (ball.y <= 0) ? 0 : bounds;
    }

    if (ball.vx < 0 && ball.x < 450) {
        updateActiveTarget('left');
    } else if (ball.vx > 0 && ball.x > 450) {
        updateActiveTarget('right');
    }

    if ((ball.vx < 0 && ball.x <= 30 && ball.x + 16 >= 20) || (ball.vx > 0 && ball.x + 16 >= 870 && ball.x <= 880)) {
      let hitLeft = (ball.vx < 0);
      let pad = hitLeft ? padL : padR;
      if (ball.y >= pad.y - 16 && ball.y <= pad.y + pad.h) {
        speedMult = Math.min(speedMult * 1.03, MAX_SPEED_MULT);
        ball.vx = (ball.vx > 0 ? -8 : 8) * speedMult;
        let impact = (ball.y - (pad.y + pad.h / 2)) / (pad.h / 2);
        ball.vy += impact * 2; 
        hitCount++;
        shakeFrames = 8;
        createWave(hitLeft ? 30 : 870, ball.y + 8, false);
      }
    }

    if (ball.x <= 0 || ball.x >= 900) {
        ball.vx *= -1;
    }

    for (let i = waves.length - 1; i >= 0; i--) {
        let w = waves[i];
        w.r += w.speed;
        w.opacity -= w.fade;

        if (w.opacity <= 0) {
            wavesContainer.removeChild(w.element);
            waves.splice(i, 1);
            continue;
        }

        w.element.setAttribute('r', w.r);
        w.element.setAttribute('stroke-opacity', w.opacity);

        if (!w.isSecondary) {
            nodes.forEach((n, idx) => {
                if (w.hitNodes.has(idx)) return;
                let dist = Math.sqrt(Math.pow(w.x - n.x, 2) + Math.pow(w.y - n.y, 2));
                if (Math.abs(dist - w.r) <= w.speed) {
                    w.hitNodes.add(idx);
                    createWave(n.x, n.y, true);
                }
            });
        }
    }

    ballHistory.unshift({ x: ball.x, y: ball.y });
    if (ballHistory.length > Math.max(5, Math.floor(12 * speedMult))) ballHistory.pop();

    while (ballTrailEl.childNodes.length < ballHistory.length) {
      let r = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
      r.setAttribute('fill', 'white');
      ballTrailEl.appendChild(r);
    }
    while (ballTrailEl.childNodes.length > ballHistory.length) ballTrailEl.removeChild(ballTrailEl.firstChild);

    for (let i = 0; i < ballHistory.length; i++) {
      let seg = ballTrailEl.childNodes[i];
      seg.setAttribute('x', ballHistory[i].x);
      seg.setAttribute('y', ballHistory[i].y);
      seg.setAttribute('width', 16 * (1 - (i / ballHistory.length) * 0.5));
      seg.setAttribute('height', 16 * (1 - (i / ballHistory.length) * 0.5));
      seg.setAttribute('opacity', (1 - (i / ballHistory.length)) * 0.32);
    }

    padL.vy += (padL.target - padL.y) * 0.05;
    padL.vy *= 0.85;
    padL.y += padL.vy;

    padR.vy += (padR.target - padR.y) * 0.05;
    padR.vy *= 0.85;
    padR.y += padR.vy;

    let jitterX = (Math.random() > 0.95) ? (Math.random() - 0.5) * 2 : 0;
    let jitterY = (Math.random() > 0.95) ? (Math.random() - 0.5) * 2 : 0;
    gameContentEl.setAttribute('transform', 'translate(' + jitterX + ',' + jitterY + ')');

    if (shakeFrames > 0) {
        let sx = (Math.random() - 0.5) * 6;
        let sy = (Math.random() - 0.5) * 6;
        textGroupEl.setAttribute('transform', 'translate(' + sx + ',' + sy + ')');
        shakeFrames--;
    } else {
        textGroupEl.removeAttribute('transform');
    }

    ballEl.setAttribute('x', ball.x);
    ballEl.setAttribute('y', ball.y);
    padLEl.setAttribute('y', padL.y);
    padREl.setAttribute('y', padR.y);

    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
}
